INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'self-critical', 'adj.', '/ˌself ˈkrɪtɪk(ə)l/', '自我批评的;自我批判的', 'Many people are the most self-critical about their own looks.', '许多人对自己的外貌最为苛刻。', 'Its All About Me', 1, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be too self-critical', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'boost', 'v.', '/buːst/', '促进;增强;提升', 'Each kind comment seemed to boost her confidence a little.', '每一句善意的评论似乎都能稍稍增强她的自信。', 'Its All About Me', 2, 0, 'senior', 'wordlist', 'elective3', 'U1', 'boost one''s confidence', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pretend', 'v.', '/prɪˈtend/', '假装;装作', 'People who pretend to be someone else often misjudge themselves.', '假装成别人的人往往会误判自己。', 'Its All About Me', 3, 0, 'senior', 'wordlist', 'elective3', 'U1', 'pretend to be', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'identical', 'adj.', '/aɪˈdentɪk(ə)l/', '完全相同的;非常相似的', 'He owned five identical shirts and wore them day after day.', '他有五件一模一样的衬衫,日复一日地穿。', 'Its All About Me', 4, 0, 'senior', 'wordlist', 'elective3', 'U1', 'identical shirts', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'dormitory', 'n.', '/ˈdɔːmɪt(ə)ri/', '寝室;宿舍', 'When he moved into the dormitory, his roommates were confused.', '他搬进宿舍时,室友们感到困惑。', 'Its All About Me', 5, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a college dormitory', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bother', 'v.', '/ˈbɒðə/', '(使)苦恼;打扰', 'For a long time, her weight really bothered her.', '很长一段时间,她的体重真的让她很苦恼。', 'Its All About Me', 6, 0, 'senior', 'wordlist', 'elective3', 'U1', 'bother sb', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'pill', 'n.', '/pɪl/', '药丸;药片', 'She tried diets and weight-loss pills, but they only harmed her health.', '她试过节食和减肥药,但这些只损害了她的健康。', 'Its All About Me', 7, 0, 'senior', 'wordlist', 'elective3', 'U1', 'weight-loss pills', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'acknowledge', 'v.', '/əkˈnɒlɪdʒ/', '承认(属实);认可', 'She has acknowledged that good health makes us more beautiful.', '她已经承认,健康让我们更美。', 'Its All About Me', 8, 0, 'senior', 'wordlist', 'elective3', 'U1', 'acknowledge that', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'assumption', 'n.', '/əˈsʌmpʃ(ə)n/', '假定;假设', 'We should not make assumptions about who is truly happy.', '我们不应臆断谁才是真正快乐的人。', 'Its All About Me', 9, 0, 'senior', 'wordlist', 'elective3', 'U1', 'make assumptions', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'saving', 'n.', '/ˈseɪvɪŋ/', '积蓄;存款', 'He spent all his savings on new clothes for the makeover.', '他把全部积蓄都花在了为改造形象买的新衣服上。', 'Its All About Me', 10, 0, 'senior', 'wordlist', 'elective3', 'U1', 'life savings', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'welfare', 'n.', '/ˈwelfeə/', '福利;健康幸福', 'The programme cares about the mental welfare of young people.', '这个节目关心年轻人的心理健康。', 'Its All About Me', 11, 0, 'senior', 'wordlist', 'elective3', 'U1', 'mental welfare', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'psychology', 'n.', '/saɪˈkɒlədʒi/', '心理;心理学', 'A teacher of psychology explained why we keep editing our photos.', '一位心理学老师解释了我们为何不停地修图。', 'Its All About Me', 12, 0, 'senior', 'wordlist', 'elective3', 'U1', 'the psychology of beauty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'finding', 'n.', '/ˈfaɪndɪŋ/', '研究结果;发现', 'The findings of the scar experiment surprised everyone.', '疤痕实验的研究结果让所有人都很惊讶。', 'Its All About Me', 13, 0, 'senior', 'wordlist', 'elective3', 'U1', 'the findings', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'novelist', 'n.', '/ˈnɒv(ə)lɪst/', '小说家', 'The French novelist wrote about beauty hidden behind an ugly face.', '这位法国小说家描写了丑陋面孔背后隐藏的美。', 'Its All About Me', 14, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a famous novelist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'comprehension', 'n.', '/ˌkɒmprɪˈhenʃ(ə)n/', '理解(力)', 'How he could be so cruel was beyond her comprehension.', '他怎么会如此残忍,这超出了她的理解。', 'Its All About Me', 15, 0, 'senior', 'wordlist', 'elective3', 'U1', 'beyond comprehension', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'accent', 'n.', '/ˈæks(ə)nt/', '口音;腔调;语气', 'She noticed a sad accent in the way the lonely man spoke.', '她注意到那个孤独男人说话时带着一种悲伤的语气。', 'Its All About Me', 16, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a soft accent', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'motive', 'n.', '/ˈməʊtɪv/', '动机;原因;目的', 'His real motive was to win praise from others online.', '他真正的动机是赢得网上他人的赞美。', 'Its All About Me', 17, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a hidden motive', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'freckle', 'n.', '/ˈfrek(ə)l/', '雀斑;斑点', 'The selfie app could remove every freckle from her face.', '这款自拍软件能去掉她脸上的每一颗雀斑。', 'Its All About Me', 18, 0, 'senior', 'wordlist', 'elective3', 'U1', 'remove freckles', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'enlarge', 'v.', '/ɪnˈlɑːdʒ/', '(使)扩大;放大', 'With one tap the app could enlarge her eyes and slim her jaw.', '轻轻一点,软件就能放大她的眼睛、瘦脸。', 'Its All About Me', 19, 0, 'senior', 'wordlist', 'elective3', 'U1', 'enlarge the eyes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'narcissist', 'n.', '/nɑːˈsɪsɪst/', '自我陶醉者;自恋的人', 'Her father called her a narcissist for editing so many selfies.', '她父亲因为她修了太多自拍而说她自恋。', 'Its All About Me', 20, 0, 'senior', 'wordlist', 'elective3', 'U1', 'call sb a narcissist', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'obsessive', 'adj.', '/əbˈsesɪv/', '痴迷的;过度的(含贬义)', 'His obsessive photo editing showed a lack of self-confidence.', '他对修图的痴迷反映出缺乏自信。', 'Its All About Me', 21, 0, 'senior', 'wordlist', 'elective3', 'U1', 'obsessive editing', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'misjudge', 'v.', '/ˌmɪsˈdʒʌdʒ/', '判断错误;错看', 'People who hide their real selves tend to misjudge themselves.', '隐藏真实自我的人往往会错看自己。', 'Its All About Me', 22, 0, 'senior', 'wordlist', 'elective3', 'U1', 'misjudge oneself', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'lipstick', 'n.', '/ˈlɪpstɪk/', '唇膏;口红', 'His sister owned seventeen lipsticks and could never choose one.', '他姐姐有十七支口红,却总也选不出一支。', 'Its All About Me', 23, 0, 'senior', 'wordlist', 'elective3', 'U1', 'seventeen lipsticks', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'roommate', 'n.', '/ˈruːmˌmeɪt/', '室友', 'His roommates secretly signed him up for a makeover show.', '他的室友们偷偷给他报名了一档形象改造节目。', 'Its All About Me', 24, 0, 'senior', 'wordlist', 'elective3', 'U1', 'my roommate', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bizarre', 'adj.', '/bɪˈzɑː/', '古怪的;奇异的', 'Being reviewed from head to toe felt bizarre to him at first.', '被从头到脚地评头论足,起初让他觉得很别扭。', 'Its All About Me', 25, 0, 'senior', 'wordlist', 'elective3', 'U1', 'feel bizarre', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'makeover', 'n.', '/ˈmeɪkəʊvə/', '(形象的)改造;装扮', 'After the makeover, he finally saw himself as handsome.', '改造之后,他终于觉得自己很帅。', 'Its All About Me', 26, 0, 'senior', 'wordlist', 'elective3', 'U1', 'after the makeover', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'overlook', 'v.', '/ˌəʊvəˈlʊk/', '忽视;忽略', 'Inner beauty matters most, but outer beauty should not be overlooked.', '内在美最重要,但外在美也不应被忽视。', 'Its All About Me', 27, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be overlooked', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'stereotype', 'n.', '/ˈsteriətaɪp/', '模式化的成见;刻板印象', 'She stayed confident in an industry full of beauty stereotypes.', '在一个充满审美刻板印象的行业里,她依然自信。', 'Its All About Me', 28, 0, 'senior', 'wordlist', 'elective3', 'U1', 'beauty stereotypes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'skinny', 'adj.', '/ˈskɪni/', '极瘦的;皮包骨的', 'She would rather be large and happy than skinny and unhealthy.', '她宁愿丰满而快乐,也不愿骨瘦如柴又不健康。', 'Its All About Me', 29, 0, 'senior', 'wordlist', 'elective3', 'U1', 'skinny and unhealthy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'frightful', 'adj.', '/ˈfraɪtf(ə)l/', '可怕的;吓人的', 'People thought the character looked frightful, but he was kind.', '人们觉得这个角色样子可怕,但他其实很善良。', 'Its All About Me', 30, 0, 'senior', 'wordlist', 'elective3', 'U1', 'look frightful', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'monstrous', 'adj.', '/ˈmɒnstrəs/', '丑陋的;骇人的', 'Despite his monstrous appearance, he had a gentle heart.', '尽管外表骇人,他却有一颗温柔的心。', 'Its All About Me', 31, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a monstrous look', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'righteous', 'adj.', '/ˈraɪtʃəs/', '正派的;正直的', 'He may seem strange, yet he is just and righteous inside.', '他看上去也许怪异,但内心正直公道。', 'Its All About Me', 32, 0, 'senior', 'wordlist', 'elective3', 'U1', 'just and righteous', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'outward', 'adj.', '/ˈaʊtwəd/', '外表的;表面的', 'His outward appearance hid a timid and sensitive character.', '他外表之下藏着一颗胆怯而敏感的心。', 'Its All About Me', 33, 0, 'senior', 'wordlist', 'elective3', 'U1', 'outward appearance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'timid', 'adj.', '/ˈtɪmɪd/', '胆小的;胆怯的', 'Behind his fierce face was a timid and gentle soul.', '凶猛的面孔背后,是一个胆怯而温和的灵魂。', 'Its All About Me', 34, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a timid character', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'coward', 'n.', '/ˈkaʊəd/', '胆小鬼;懦夫', 'He believes he is a coward, yet he acts bravely when afraid.', '他认为自己是懦夫,但害怕时仍勇敢行事。', 'Its All About Me', 35, 0, 'senior', 'wordlist', 'elective3', 'U1', 'be a coward', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'bookish', 'adj.', '/ˈbʊkɪʃ/', '好读书的;书呆子气的', 'The bookish boy with untidy hair was braver than he looked.', '那个头发乱乱、爱读书的男孩比看上去要勇敢。', 'Its All About Me', 36, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a bookish boy', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'loyal', 'adj.', '/ˈlɔɪəl/', '忠诚的;忠实的', 'In reality, he is brave, loyal and always ready to help.', '实际上,他勇敢、忠诚,而且随时愿意帮忙。', 'Its All About Me', 37, 0, 'senior', 'wordlist', 'elective3', 'U1', 'brave and loyal', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'graceful', 'adj.', '/ˈɡreɪsf(ə)l/', '优美的;优雅的', 'She was as graceful as he was plain and repulsive.', '她有多优雅,他就有多平凡而丑陋。', 'Its All About Me', 38, 0, 'senior', 'wordlist', 'elective3', 'U1', 'so graceful', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'repulsive', 'adj.', '/rɪˈpʌlsɪv/', '令人厌恶的', 'Many people found him repulsive, yet she felt only pity.', '很多人觉得他令人厌恶,而她只感到怜悯。', 'Its All About Me', 39, 0, 'senior', 'wordlist', 'elective3', 'U1', 'look repulsive', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'defect', 'n.', '/dɪˈfekt/', '缺点;缺陷;毛病', 'Every moment she noticed a fresh defect in his face.', '每一刻她都会发现他脸上一处新的缺陷。', 'Its All About Me', 40, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a fresh defect', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'compassion', 'n.', '/kəmˈpæʃ(ə)n/', '怜悯;同情', 'She spoke with heartfelt compassion for the lonely man.', '她带着真挚的怜悯对那个孤独的人说话。', 'Its All About Me', 41, 0, 'senior', 'wordlist', 'elective3', 'U1', 'with compassion', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'exquisite', 'adj.', '/ɪkˈskwɪzɪt/', '精美的;精致的', 'Next to her exquisite beauty, he felt even uglier.', '在她精致的美貌旁,他觉得自己更丑了。', 'Its All About Me', 42, 0, 'senior', 'wordlist', 'elective3', 'U1', 'exquisite beauty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'immense', 'adj.', '/ɪˈmens/', '巨大的;极大的', 'When he compared himself to her, he felt immense pity.', '当他把自己和她相比时,感到无比的自怜。', 'Its All About Me', 43, 0, 'senior', 'wordlist', 'elective3', 'U1', 'immense pity', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'resemble', 'v.', '/rɪˈzemb(ə)l/', '像;与……相似', 'He said he must resemble some savage creature to her.', '他说,在她眼里他一定像某种野蛮的怪物。', 'Its All About Me', 44, 0, 'senior', 'wordlist', 'elective3', 'U1', 'resemble a creature', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'profound', 'adj.', '/prəˈfaʊnd/', '(感情)深切的;深刻的', 'She listened to him with profound tenderness.', '她带着深切的温柔听他诉说。', 'Its All About Me', 45, 0, 'senior', 'wordlist', 'elective3', 'U1', 'profound tenderness', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'heartfelt', 'adj.', '/ˈhɑːtfelt/', '衷心的;诚挚的', 'Her heartfelt words showed how deeply she cared.', '她诚挚的话语显示出她有多么在乎。', 'Its All About Me', 46, 0, 'senior', 'wordlist', 'elective3', 'U1', 'heartfelt words', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'jawline', 'n.', '/ˈdʒɔːlaɪn/', '下巴的轮廓', 'The app could slim her jawline with a single tap.', '这款软件轻轻一点就能让她的下巴线条变瘦。', 'Its All About Me', 47, 0, 'senior', 'wordlist', 'elective3', 'U1', 'slim the jawline', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (12, 'tenderness', 'n.', '/ˈtendənɪs/', '柔情;温柔', 'A look of tenderness slowly softened her face.', '一抹柔情渐渐让她的脸庞柔和起来。', 'Its All About Me', 48, 0, 'senior', 'wordlist', 'elective3', 'U1', 'a look of tenderness', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u1.01', '①what 引导的主语从句(从句内缺成分)', 'A2', 12, '外研社版选择性必修第三册 U1 — 当主语从句内部缺主语或宾语时,用 what(= the thing that/which)同时充当连接词并补足缺失成分;that/whether 不能补足缺成分,which 无先行词,都不行。', 1, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u1.02', '②that / whether 引导的主语从句(从句完整)', 'A2', 12, '外研社版选择性必修第三册 U1 — 从句结构完整、陈述一个事实时用 that(只起连接、不充当成分);表示''是否''的开放/未定语义时用 whether;if 不能引导句首主语从句。', 2, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe3u1.03', '③形式主语 it · whoever / whatever 作主语', 'A2', 12, '外研社版选择性必修第三册 U1 — 把主语从句(that/to do/whether)后置、句首用形式主语 it;指''任何人''用 whoever、指''任何事物''用 whatever 引导主语从句。', 3, 'elective3', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ makes a person beautiful is not only a pretty face."', 'what', 'that', 'whether', 'which', 'A', '从句 ''makes a person beautiful'' 缺主语,需要既作连接词又补主语的词 → what(= the thing that)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ he said about my selfies really upset me."', 'that', 'what', 'which', 'whether', 'B', 'said 后缺宾语,用 what 补足并连接;that 引导的主语从句必须完整。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ truly matters is who you are on the inside."', 'that', 'it', 'what', 'whether', 'C', 'matters 前缺主语 → what(= the thing that)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ I post online shows only my happiest moments."', 'that', 'whether', 'which', 'what', 'D', 'post 后缺宾语,用 what 补足。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ surprised his roommates was his calm, honest reply."', 'what', 'that', 'which', 'it', 'A', 'surprised 前缺主语 → what。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ the editing app changed was just my appearance."', 'that', 'what', 'whether', 'which', 'B', 'changed 后缺宾语 → what。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ counts most is a kind and honest heart."', 'that', 'it', 'what', 'which', 'C', 'counts 前缺主语 → what。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ she admires in Emma is her quiet self-confidence."', 'that', 'which', 'whether', 'what', 'D', 'admires 后缺宾语 → what。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ worried her parents was her endless photo editing."', 'what', 'that', 'it', 'which', 'A', 'worried 前缺主语 → what。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ we show the world online is not always the truth."', 'that', 'what', 'whether', 'which', 'B', 'show 后缺宾语 → what。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ lies behind every perfect photo is real pressure."', 'that', 'which', 'what', 'it', 'C', 'lies 前缺主语 → what。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ I really need is the courage to be myself."', 'that', 'whether', 'which', 'what', 'D', 'need 后缺宾语 → what。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ defines us most is our character, not our looks."', 'what', 'that', 'it', 'which', 'A', 'defines 前缺主语 → what。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ young people share online can shape their self-image."', 'that', 'what', 'whether', 'which', 'B', 'share 后缺宾语 → what。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ impressed the doctor most was her healthy attitude."', 'that', 'which', 'what', 'it', 'C', 'impressed 前缺主语 → what。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ he values most is being true to himself."', 'that', 'whether', 'which', 'what', 'D', 'values 后缺宾语 → what。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ happened after the makeover changed his whole view."', 'what', 'that', 'it', 'which', 'A', 'happened 前缺主语 → what。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ the speaker described was a simple but clever experiment."', 'that', 'what', 'whether', 'which', 'B', 'described 后缺宾语 → what。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ keeps her confident is her inner strength, not her makeup."', 'that', 'which', 'what', 'it', 'C', 'keeps 前缺主语 → what。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.01'), '"____ I want others to see is the real me."', 'that', 'whether', 'which', 'what', 'D', 'see 后缺宾语 → what。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ inner beauty matters is something we all should remember."', 'that', 'what', 'whether', 'if', 'A', '从句完整、陈述事实 → that;无缺成分故非 what,语义肯定故非 whether/if。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ she edits every single photo clearly worries her father."', 'what', 'that', 'if', 'whether', 'B', '从句完整、是既成事实 → that。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ good health makes us happier is now widely accepted."', 'what', 'whether', 'that', 'if', 'C', '陈述被普遍接受的事实 → that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ Anthony completely changed his style amazed his roommates."', 'what', 'if', 'whether', 'that', 'D', '从句完整、是已发生的事 → that。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ true beauty comes from within is the writer''s main point."', 'that', 'what', 'whether', 'if', 'A', '陈述一个观点(事实)→ that。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ Emma feels proud of her body inspires many readers."', 'what', 'that', 'if', 'whether', 'B', '从句完整、陈述事实 → that。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ a positive image can boost confidence is certainly true."', 'what', 'whether', 'that', 'if', 'C', '谓语 is certainly true 指向事实 → that。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ the model stayed confident encouraged thousands of girls."', 'what', 'if', 'whether', 'that', 'D', '从句完整、是事实 → that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ kindness shapes real beauty is a lesson worth learning."', 'that', 'what', 'whether', 'if', 'A', '陈述事实 → that。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ he finally accepted himself made his whole family glad."', 'what', 'that', 'if', 'whether', 'B', '从句完整、已发生 → that。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ external beauty really matters is still debated by many."', 'if', 'that', 'whether', 'what', 'C', '谓语 is still debated 表''是否''的争论 → whether;if 不能引导句首主语从句。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ she should delete the selfie app is a hard choice for Jade."', 'if', 'what', 'that', 'whether', 'D', '表''是否要删''的两难 → whether。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ looks truly affect first impressions is worth discussing."', 'whether', 'if', 'that', 'what', 'A', '谓语 is worth discussing 暗含未定 → whether。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ we should change our appearance depends on our reasons."', 'if', 'whether', 'what', 'that', 'B', 'depends on 表条件性、未定 → whether。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ his makeover was really a good idea is not yet clear."', 'if', 'that', 'whether', 'what', 'C', 'is not yet clear 表未定 → whether。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ beauty lies inside or outside has long been argued about."', 'if', 'what', 'that', 'whether', 'D', '''…inside or outside'' 的两可 → whether。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ to edit her photos or leave them alone troubled Jade daily."', 'whether', 'if', 'that', 'what', 'A', '只有 whether 能接动词不定式作主语;if 不可。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ people can ever fully accept their looks remains uncertain."', 'if', 'whether', 'what', 'that', 'B', 'remains uncertain 表未定 → whether。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ social media helps or harms teenagers is widely discussed."', 'if', 'that', 'whether', 'what', 'C', '''helps or harms'' 两可 → whether。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.02'), '"____ she would dare to join the show was still in doubt."', 'if', 'what', 'that', 'whether', 'D', 'was still in doubt 表未定 → whether。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ is important that we accept who we really are."', 'It', 'What', 'That', 'There', 'A', '真正主语是后置的 that 从句,句首用形式主语 → It。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ is true that outer beauty often fades with time."', 'What', 'It', 'This', 'There', 'B', '形式主语 It 指代后面的 that 从句。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ is no surprise that confidence makes people shine."', 'What', 'There', 'It', 'That', 'C', 'It is no surprise that…,形式主语 It。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ takes real courage to post a photo without any editing."', 'What', 'That', 'This', 'It', 'D', '真正主语是后面的不定式,形式主语用 It。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ is up to you whether you change your look or not."', 'It', 'What', 'That', 'There', 'A', '形式主语 It 指代后置的 whether 从句。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ feels wonderful to be at ease with your own body."', 'What', 'It', 'That', 'This', 'B', '后置不定式作真正主语,形式主语 It。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ is clear that good health is a kind of beauty."', 'What', 'This', 'It', 'There', 'C', 'It is clear that…,形式主语 It。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ is hard to ignore the pressure from social media."', 'What', 'That', 'There', 'It', 'D', '后置不定式作真正主语,形式主语 It。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ is worth remembering that kindness shapes true beauty."', 'It', 'What', 'This', 'That', 'A', 'It is worth remembering that…,形式主语 It。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ was foolish of him to judge people only by their looks."', 'What', 'It', 'That', 'There', 'B', 'It was foolish of sb to do,形式主语 It。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ stands behind the camera controls the final image."', 'Whatever', 'Whomever', 'Whoever', 'Anyone', 'C', '指''任何站在相机后的人''、从句缺主语 → Whoever。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ accepts herself first will gain real confidence."', 'Whatever', 'Whomever', 'Whichever', 'Whoever', 'D', 'herself 指人、从句缺主语 → Whoever。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ truly loves you cares about your heart, not your face."', 'Whoever', 'Whatever', 'Whomever', 'Anyone', 'A', '指''任何爱你的人''、缺主语 → Whoever。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ praises only your looks may not be a true friend."', 'Whatever', 'Whoever', 'Whichever', 'Whomever', 'B', '指人、缺主语 → Whoever。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ stands before the mirror sees only one side of beauty."', 'Whatever', 'Whomever', 'Whoever', 'Anyone', 'C', '指''任何照镜子的人''、缺主语 → Whoever。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ you post online may stay there forever."', 'Whoever', 'However', 'Whichever', 'Whatever', 'D', '指''任何你发的东西''、post 后缺宾语 → Whatever。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ the camera shows is only a small part of the truth."', 'Whatever', 'Whoever', 'However', 'Whichever', 'A', '指''相机所显示的任何事物''、shows 后缺宾语 → Whatever。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ he says about my pictures cannot change how I feel."', 'Whoever', 'Whatever', 'However', 'Whomever', 'B', '指''他说的任何话''、says 后缺宾语 → Whatever。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ makes you feel confident is surely worth keeping."', 'However', 'Whichever', 'Whatever', 'Wherever', 'C', '指''任何让你自信的事物''、缺主语 → Whatever。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective3' AND unit='U1' AND code='fe3u1.03'), '"____ they print in those magazines is not always real."', 'Whoever', 'However', 'Whomever', 'Whatever', 'D', '指''他们印出的任何东西''、print 后缺宾语 → Whatever。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Living Behind a Screen', 'Jade has always thought of herself as plain-looking, so she felt excited when she found a selfie app. With a single tap, it could remove her freckles, enlarge her eyes and slim her jawline. Soon she was spending hours every day editing her photos, posting them and checking her phone again and again for comments. Every new like seemed to boost her confidence, even if only for a moment. Her father called her a narcissist, but Jade replied that her pictures were hurting no one. A psychologist, however, sees a different story. To him, such obsessive editing is a sign that a person lacks self-confidence and badly wants attention. The polished face Jade shows the world is simply not real. The danger, he warns, is that people who keep pretending to be someone they are not slowly begin to misjudge who they truly are.', '说明·社交媒体上的形象', 144, '[{"q":"Why does Jade enjoy using the selfie app so much?","answer":"A","options":["The likes and comments make her feel more confident.","It helps her make new friends at school.","It earns her money from advertisers.","It teaches her how to take real photos."],"explanation":"原文 ''Every new like seemed to boost her confidence'' 的转述。"},{"q":"How does the psychologist explain Jade''s behaviour?","answer":"B","options":["He thinks it is a harmless and healthy hobby.","He sees it as a sign of low confidence and a wish for attention.","He believes it will make her a professional model.","He says it proves she is naturally beautiful."],"explanation":"原文 ''a sign that a person lacks self-confidence and badly wants attention'' 的转述。"},{"q":"What does the psychologist warn may happen to such people?","answer":"A","options":["They may start to see their true selves wrongly.","They will become famous very quickly.","They will lose interest in their phones.","They will delete all their photos one day."],"explanation":"末句 ''…slowly begin to misjudge who they truly are'' 的转述。"}]'::jsonb, '[{"word":"selfie","cn":"自拍"},{"word":"obsessive","cn":"痴迷的"},{"word":"misjudge","cn":"错判;看错"}]'::jsonb, 2, 'elective3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'A Surprising New You', 'Anthony had never cared about how he looked. While his sister owned seventeen lipsticks and spent ages choosing one each morning, he simply wore five identical shirts and five identical pairs of trousers. In his dormitory, his roommates were confused to see him in the same clothes day after day. As a joke, they signed him up for a television show called A New You. At first the whole idea felt bizarre, and he hated being reviewed from head to toe. Yet he was amazed by how good he looked after the makeover. For the first time, he saw himself as a handsome, well-presented young man. That experience changed his thinking. He realised that outer beauty is not worthless after all. It can be a way of expressing our personality and of leaving a warm, positive first impression on the people we meet. Even so, he knew it was only one part of who he was.', '记叙·形象改造的发现', 156, '[{"q":"What surprised Anthony''s roommates about him?","answer":"B","options":["He owned many bottles of lipstick.","He always wore the very same kind of clothes.","He refused to live in the dormitory.","He spent hours choosing his outfit."],"explanation":"原文 ''his roommates were confused to see him in the same clothes day after day'' 的转述。"},{"q":"How did Anthony feel about the show at the beginning?","answer":"C","options":["He was proud and excited to take part.","He thought it was a waste of money.","He found it strange and disliked being judged.","He believed it would make him famous."],"explanation":"原文 ''felt bizarre, and he hated being reviewed from head to toe'' 的转述。"},{"q":"What did Anthony finally come to understand about outer beauty?","answer":"D","options":["It is completely useless to everyone.","It is the only thing that matters in life.","It should always be ignored by serious people.","It can help express character and leave a good impression."],"explanation":"原文 ''…a way of expressing our personality and of leaving a warm, positive first impression'' 的转述。"}]'::jsonb, '[{"word":"identical","cn":"一模一样的"},{"word":"makeover","cn":"形象改造"},{"word":"bizarre","cn":"古怪的"}]'::jsonb, 2, 'elective3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'Large and Happy', 'Ever since she was little, Emma had been bigger than the other girls, and for years this troubled her deeply. Strangers would stare at her, and she hated the way she looked. Her worry pushed her to try every method she could think of to lose weight, including strict diets and weight-loss pills. Sadly, all of this brought her nothing but pain and poor health. Everything changed the day she read about a plus-size model who refused to follow the usual beauty stereotypes. Although larger than most models, the woman was attractive and full of confidence. Her story made Emma rethink what being beautiful really means. She decided that her health, both of body and of mind, mattered more than her size. Today Emma exercises a couple of times a week, not to become thin, but simply to feel well. As she puts it, being large and happy is far better than being skinny and unhappy.', '记叙·身材自信', 156, '[{"q":"What did Emma do because she hated the way she looked?","answer":"A","options":["She tried many ways to lose weight, harming her health.","She stopped going outside completely.","She became a fashion model herself.","She asked doctors to change her face."],"explanation":"原文 ''…try every method she could think of to lose weight… nothing but pain and poor health'' 的转述。"},{"q":"What effect did the plus-size model''s story have on Emma?","answer":"B","options":["It made her start a strict new diet.","It led her to rethink the meaning of beauty.","It made her give up exercise for good.","It made her feel jealous and sad."],"explanation":"原文 ''made Emma rethink what being beautiful really means'' 的转述。"},{"q":"Why does Emma exercise now?","answer":"C","options":["To become as thin as possible.","To win a beauty competition.","To keep healthy and feel good, not to be thin.","To please the strangers who stare at her."],"explanation":"原文 ''not to become thin, but simply to feel well'' 的转述。"}]'::jsonb, '[{"word":"stereotype","cn":"刻板印象"},{"word":"plus-size","cn":"大码的"},{"word":"skinny","cn":"极瘦的"}]'::jsonb, 2, 'elective3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Scar That Was Not There', 'Some years ago, a researcher named Dr Robert Kleck carried out a clever experiment about how we see ourselves. Using Hollywood-style make-up, his team painted an ugly scar onto each volunteer''s face and showed it to them in a mirror. Then, telling the volunteers that the make-up needed fixing, the team secretly wiped the scar away. The volunteers, however, still believed it was there. They went outside and watched how strangers treated them. Afterwards, most of them reported that people had been ruder and less kind, and that others had kept staring at the scar that no longer existed. The finding was striking. The volunteers had not really measured how others behaved; instead, they had measured their own fears. In other words, who we are lives mainly inside our heads. If people choose to feel ugly or unwelcome, the experiment suggests, they will often start to feel exactly that way.', '说明·疤痕实验', 150, '[{"q":"What did Dr Kleck''s team secretly do before the volunteers went outside?","answer":"D","options":["They made the scar look even worse.","They gave each volunteer a small mirror.","They painted a second scar on the face.","They removed the scar without telling them."],"explanation":"原文 ''secretly wiped the scar away'' 的转述。"},{"q":"What did most volunteers report after going outside?","answer":"A","options":["That people treated them worse and stared at the scar.","That strangers were friendlier than usual.","That nobody noticed them at all.","That the make-up had completely disappeared."],"explanation":"原文 ''people had been ruder and less kind, and… kept staring'' 的转述。"},{"q":"What is the main lesson of the experiment?","answer":"B","options":["Make-up can change how strangers behave.","How we feel about ourselves shapes what we notice.","Scars always make people unkind.","Volunteers should never trust mirrors."],"explanation":"原文 ''who we are lives mainly inside our heads'' 的转述。"}]'::jsonb, '[{"word":"scar","cn":"疤痕"},{"word":"volunteer","cn":"志愿者"},{"word":"finding","cn":"研究结果"}]'::jsonb, 2, 'elective3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'More Than Skin Deep', 'We often hear that it is a pretty person''s world, and there is some truth in that. Studies show that a pleasant appearance can open doors and leave a good first impression. Yet the doctor in this unit reminds us not to overlook what lies beneath the surface. Inner beauty, he argues, is by far the more important kind, but external beauty still plays its part. Making a reasonable effort with how we look can boost our confidence and help others warm to us. The danger comes when appearance becomes everything. People who spend all their energy chasing a perfect face often grow more self-critical, not less. They make assumptions about how others judge them and forget that true attractiveness grows from kindness, honesty and good health. The wisest view, perhaps, is a balanced one: care for your appearance, but never let it decide your worth. After all, what people remember is how you made them feel.', '议论·内在与外在美', 157, '[{"q":"According to the writer, what can a pleasant appearance do?","answer":"C","options":["It can solve every problem in life.","It can replace honesty and kindness.","It can create chances and a good first impression.","It can make inner beauty unnecessary."],"explanation":"原文 ''a pleasant appearance can open doors and leave a good first impression'' 的转述。"},{"q":"What problem does the writer see in chasing a perfect face?","answer":"D","options":["It always costs too much money.","It makes people forget how to take photos.","It improves health too quickly.","People often become more self-critical, not happier."],"explanation":"原文 ''often grow more self-critical, not less'' 的转述。"},{"q":"What is the writer''s advice in the end?","answer":"A","options":["Look after your appearance without letting it define your worth.","Ignore your appearance completely.","Spend all your time on your looks.","Trust only what others say about you."],"explanation":"原文 ''care for your appearance, but never let it decide your worth'' 的转述。"}]'::jsonb, '[{"word":"overlook","cn":"忽视"},{"word":"self-critical","cn":"自我批判的"},{"word":"assumption","cn":"假设;臆断"}]'::jsonb, 2, 'elective3', 'U1', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (12, 'The Heart Behind the Face', 'In a famous French novel, a man named Quasimodo is born with a frightful, almost monstrous appearance. People judge him by his looks alone and treat him cruelly, never guessing at the gentle heart he hides. When a kind young woman named Esmeralda offers him a simple drink of water, that small act of mercy captures his heart forever. Later, when she is in great danger, he risks everything to save her. As the two sit together, she keeps noticing fresh defects in his face, from his bent back to his single eye. Yet she also senses such deep sadness and gentleness in him that, little by little, her fear turns into compassion. Quasimodo, deaf and lonely, speaks of his ugliness with painful honesty. The story has been loved for almost two hundred years because it asks a question that still matters today: should a person be measured by an outward shape, or by the quality of the heart within?', '文学·丑陋外表下的美', 160, '[{"q":"How do most people treat Quasimodo?","answer":"B","options":["They admire his great strength.","They judge him cruelly because of his looks.","They are frightened of his clever mind.","They quickly become his close friends."],"explanation":"原文 ''judge him by his looks alone and treat him cruelly'' 的转述。"},{"q":"What changes Esmeralda''s feelings towards Quasimodo?","answer":"C","options":["She discovers that he is rich.","She learns that he is famous.","She senses his sadness and gentleness, and feels pity.","She finds that his face is beautiful."],"explanation":"原文 ''…her fear turns into compassion'' 的转述。"},{"q":"Why is the story still loved today, according to the passage?","answer":"D","options":["It describes the city of Paris in detail.","It teaches readers how to swim.","It explains how to write a novel.","It raises a question about looks versus the heart."],"explanation":"原文 ''…should a person be measured by an outward shape, or by the quality of the heart within'' 的转述。"}]'::jsonb, '[{"word":"monstrous","cn":"骇人的"},{"word":"compassion","cn":"怜悯"},{"word":"defect","cn":"缺陷"}]'::jsonb, 2, 'elective3', 'U1', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'Learning to Love My Freckles', 'When I was younger, I hated the freckles on my face and thought they made me ugly. Every morning I would (1)____ at the mirror and wish they would disappear. I begged my mother to buy a cream that promised to (2)____ them, but nothing worked. For a long time this small thing really (3)____ me, and I avoided having my photo taken. Then one summer my art teacher told me that my freckles were (4)____, like tiny stars across my cheeks. Her words slowly changed the way I (5)____ myself. I began to (6)____ that a face without any marks would be rather boring. Now, instead of hiding, I feel (7)____ of my freckles. They are part of who I am, and they make me (8)____ from everyone else. I have learned an important (9)____: real beauty is not about having a perfect face. It is about being (10)____ with the face you already have.', 156, 2, '[{"q":"1","answer":"A","options":["stare","throw","drive","cook"],"explanation":"stare at the mirror 盯着镜子;其余动词不搭配。"},{"q":"2","answer":"B","options":["borrow","remove","count","sell"],"explanation":"remove the freckles 去掉雀斑。"},{"q":"3","answer":"C","options":["thanked","invited","bothered","followed"],"explanation":"really bothered me 让我苦恼。"},{"q":"4","answer":"D","options":["empty","loud","late","beautiful"],"explanation":"freckles were beautiful 很美;形容词同类。"},{"q":"5","answer":"A","options":["saw","sold","drove","fed"],"explanation":"the way I saw myself 看待自己的方式。"},{"q":"6","answer":"B","options":["refuse","realise","forget","escape"],"explanation":"began to realise 开始意识到。"},{"q":"7","answer":"C","options":["afraid","sorry","proud","tired"],"explanation":"feel proud of 为……自豪。"},{"q":"8","answer":"D","options":["absent","silent","asleep","different"],"explanation":"make me different from 与众不同。"},{"q":"9","answer":"A","options":["lesson","ticket","engine","garden"],"explanation":"an important lesson 一个重要的道理。"},{"q":"10","answer":"B","options":["angry","happy","hungry","busy"],"explanation":"be happy with 对……满意;形容词同类。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'Stop Comparing', 'Last year I spent far too much time on social media, and it slowly made me (1)____. Every day I would scroll through photos of people who seemed prettier, richer and more (2)____ than me. The more I looked, the worse I (3)____. I started to believe that my own life was dull and that I would never be good (4)____. One evening my best friend noticed how quiet I had become and asked what was (5)____. When I explained, she smiled and said that those perfect online lives are mostly not (6)____. People only post their best moments, she reminded me, and (7)____ their bad days. Her words helped me see the truth. I decided to (8)____ less time on my phone and more time with real friends. Bit by bit, I stopped (9)____ myself to strangers on a screen. Now I feel much more (10)____ about who I am.', 151, 2, '[{"q":"1","answer":"C","options":["famous","ancient","unhappy","golden"],"explanation":"made me unhappy 让我不快乐;语境为负面。"},{"q":"2","answer":"D","options":["asleep","absent","empty","confident"],"explanation":"more confident 更自信;形容词同类。"},{"q":"3","answer":"A","options":["felt","sold","drove","baked"],"explanation":"the worse I felt 我越难受。"},{"q":"4","answer":"B","options":["instead","enough","however","almost"],"explanation":"good enough 够好。"},{"q":"5","answer":"C","options":["polite","modern","wrong","cheap"],"explanation":"what was wrong 出了什么问题。"},{"q":"6","answer":"D","options":["loud","free","heavy","real"],"explanation":"not real 不真实;形容词同类。"},{"q":"7","answer":"A","options":["hide","share","enjoy","repeat"],"explanation":"hide their bad days 藏起糟糕的日子;与 ''post their best moments'' 形成对比。"},{"q":"8","answer":"B","options":["lose","spend","waste","borrow"],"explanation":"spend less time 花更少时间;固定搭配 spend time。"},{"q":"9","answer":"C","options":["selling","feeding","comparing","driving"],"explanation":"stop comparing myself 停止比较。"},{"q":"10","answer":"D","options":["sleepy","hungry","empty","positive"],"explanation":"more positive 更积极;形容词同类。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'A Speech on Inner Beauty', 'Today I want to talk about something we often (1)____: inner beauty. Our world tells us again and again that looks come first. We are taught to (2)____ a lot about our faces, our weight and our clothes. Yet the people we truly (3)____ are seldom the prettiest ones. They are the kind, the honest and the (4)____. A warm smile and a caring heart leave a far deeper (5)____ than a perfect face ever could. Of course, I am not saying that appearance does not (6)____ at all. Looking neat and tidy can (7)____ our confidence and help us make friends. The problem begins when we let our looks (8)____ everything else. So my (9)____ to you is simple. Take care of your appearance, but spend even more energy becoming a person whose (10)____ shines from the inside. That is the kind of beauty that never fades.', 148, 2, '[{"q":"1","answer":"A","options":["overlook","borrow","repair","count"],"explanation":"often overlook 常常忽视。"},{"q":"2","answer":"B","options":["sing","worry","drive","cook"],"explanation":"worry a lot about 非常担心。"},{"q":"3","answer":"C","options":["sell","feed","admire","throw"],"explanation":"the people we admire 我们敬佩的人。"},{"q":"4","answer":"D","options":["absent","empty","asleep","brave"],"explanation":"the brave 勇敢的人;形容词作名词,与 kind/honest 并列。"},{"q":"5","answer":"A","options":["impression","machine","ticket","garden"],"explanation":"leave a deeper impression 留下更深印象。"},{"q":"6","answer":"B","options":["sell","matter","drive","cook"],"explanation":"does not matter 不重要。"},{"q":"7","answer":"C","options":["lose","waste","boost","drop"],"explanation":"boost our confidence 增强自信。"},{"q":"8","answer":"D","options":["borrow","repair","count","decide"],"explanation":"let our looks decide everything 让外表决定一切。"},{"q":"9","answer":"A","options":["advice","engine","ticket","garden"],"explanation":"my advice to you 我给你的建议。"},{"q":"10","answer":"B","options":["noise","beauty","price","weather"],"explanation":"whose beauty shines 美由内而外。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'Clothes That Say Who I Am', 'For years I wore whatever everyone else wore, simply because I did not want to (1)____ out. If a certain style was popular, I bought it, even when it did not (2)____ me at all. Deep down, though, I felt like I was (3)____ to be someone I was not. Then a friend gave me a piece of (4)____ that changed things. She said that clothes can be a quiet way of (5)____ who you really are. So I began to choose pieces that I genuinely (6)____, rather than ones that were merely fashionable. To my surprise, dressing in my own style made me feel far more (7)____. People noticed the change, and a few even said I looked (8)____ than before. I learned that fashion is not about (9)____ everyone else. It is about letting your outside gently (10)____ the person you are inside.', 145, 2, '[{"q":"1","answer":"C","options":["drive","cook","stand","sing"],"explanation":"stand out 显得突出;此处不想引人注目。"},{"q":"2","answer":"D","options":["sell","feed","throw","suit"],"explanation":"did not suit me 不适合我。"},{"q":"3","answer":"A","options":["pretending","selling","driving","feeding"],"explanation":"pretending to be 假装成。"},{"q":"4","answer":"B","options":["engine","advice","ticket","garden"],"explanation":"a piece of advice 一条建议。"},{"q":"5","answer":"C","options":["selling","cooking","showing","driving"],"explanation":"a way of showing 展示……的方式。"},{"q":"6","answer":"D","options":["lost","sold","fed","liked"],"explanation":"pieces that I liked 我喜欢的衣服。"},{"q":"7","answer":"A","options":["comfortable","absent","asleep","empty"],"explanation":"feel more comfortable 更自在;形容词同类。"},{"q":"8","answer":"B","options":["louder","happier","cheaper","heavier"],"explanation":"looked happier 看起来更开心;形容词同类。"},{"q":"9","answer":"C","options":["selling","feeding","copying","driving"],"explanation":"copying everyone else 模仿别人。"},{"q":"10","answer":"D","options":["borrow","repair","count","express"],"explanation":"express the person you are 表达真实的你。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'Breaking the Editing Habit', 'I used to edit every photo before I dared to post it. I would (1)____ my skin, brighten my eyes and make my face look thinner. At first it felt (2)____, but soon it became a heavy habit. I grew (3)____ that friends would meet me and find the real me less pretty than my pictures. The (4)____ between the two faces made me anxious. One day my younger brother looked at a photo and asked why I did not look like (5)____ in real life. His simple question really made me (6)____. I realised that I was teaching myself to (7)____ my own face. So I made a quiet (8)____ to stop. The first unedited photo was hard to share, but the comments were (9)____, and nobody minded my freckles at all. Little by little, I have learned to (10)____ the face I see in the mirror every morning.', 150, 2, '[{"q":"1","answer":"A","options":["smooth","drive","cook","sing"],"explanation":"smooth my skin 把皮肤修平滑。"},{"q":"2","answer":"B","options":["absent","exciting","asleep","empty"],"explanation":"felt exciting 觉得新奇;形容词同类。"},{"q":"3","answer":"C","options":["proud","glad","afraid","calm"],"explanation":"grew afraid that 越来越担心。"},{"q":"4","answer":"D","options":["engine","ticket","garden","difference"],"explanation":"the difference between 两者的差别。"},{"q":"5","answer":"A","options":["that","those","these","them"],"explanation":"look like that 指代照片里的样子;代词单数指那张照片。"},{"q":"6","answer":"B","options":["sell","think","drive","cook"],"explanation":"made me think 让我反思。"},{"q":"7","answer":"C","options":["borrow","repair","dislike","count"],"explanation":"teaching myself to dislike 让自己讨厌自己的脸。"},{"q":"8","answer":"D","options":["engine","ticket","garden","decision"],"explanation":"a quiet decision 一个决定。"},{"q":"9","answer":"A","options":["kind","rude","loud","late"],"explanation":"comments were kind 评论很友善;形容词同类。"},{"q":"10","answer":"B","options":["borrow","accept","sell","drive"],"explanation":"learned to accept 学会接受。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (12, 'elective3', 'U1', 'Grandma''s Lesson', 'Whenever I felt sad about my looks, my grandmother had a gentle way of helping me. She would take my hand and (1)____ me a story from her own youth. As a girl, she had been teased for being too tall, and for years it (2)____ her greatly. But over time she came to (3)____ that her height was simply part of her. "The mirror," she once told me, "shows only your (4)____, never your heart." She believed that a kind word could leave a deeper (5)____ than the prettiest face. People might (6)____ you at first by your appearance, she said, but they remember you by your (7)____. Her own friends loved her not because she was (8)____, but because she was warm and honest. Those quiet talks taught me to (9)____ less about my reflection and more about the kind of person I wanted to (10)____. I still hear her gentle voice today.', 155, 2, '[{"q":"1","answer":"C","options":["sell","drive","tell","cook"],"explanation":"tell me a story 给我讲故事。"},{"q":"2","answer":"D","options":["thanked","invited","followed","troubled"],"explanation":"it troubled her greatly 让她非常苦恼。"},{"q":"3","answer":"A","options":["accept","borrow","repair","count"],"explanation":"came to accept 慢慢接受。"},{"q":"4","answer":"B","options":["engine","surface","ticket","garden"],"explanation":"shows only your surface 只显示外表。"},{"q":"5","answer":"C","options":["machine","price","impression","weather"],"explanation":"leave a deeper impression 留下更深印象。"},{"q":"6","answer":"D","options":["sell","feed","throw","judge"],"explanation":"judge you by your appearance 凭外表评判你。"},{"q":"7","answer":"A","options":["character","engine","ticket","garden"],"explanation":"remember you by your character 凭品格记住你。"},{"q":"8","answer":"B","options":["absent","pretty","asleep","empty"],"explanation":"not because she was pretty 不是因为漂亮;形容词同类。"},{"q":"9","answer":"C","options":["sing","drive","worry","cook"],"explanation":"worry less about 少在意。"},{"q":"10","answer":"D","options":["borrow","sell","repair","become"],"explanation":"the person I wanted to become 想成为的人。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 Too Many Selfies', '外研社版选择性必修第三册 U1 · dialogue', 3, 'Mia: You''ve taken about twenty selfies of the same moment, Tom.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·短文 Be Kind to Yourself', '外研社版选择性必修第三册 U1 · passage', 2, 'Here is a simple thought for anyone who feels unhappy with their looks.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 A New Haircut', '外研社版选择性必修第三册 U1 · dialogue', 3, 'Leo: Wow, Anna, you''ve cut your hair really short. It looks great.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·短文 First Impressions', '外研社版选择性必修第三册 U1 · passage', 2, 'When we meet someone new, we often judge them in just a few seconds.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·对话 Exercise for Health', '外研社版选择性必修第三册 U1 · dialogue', 3, 'Sam: You go running twice a week now. Are you trying to lose weight?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (12, 'U1 听力·短文 Beauty Within a Book', '外研社版选择性必修第三册 U1 · passage', 2, 'In one famous old novel, a man is born with a frightening face.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (12, 'Introduce a Person You Find Truly Beautiful(介绍一个你认为真正美的人)', 'The Most Beautiful Person I Know', '本单元的主题是''真正的美''。请用英语写一篇约80词的短文,介绍一个你认为''真正美''的人(可以是家人、朋友或你敬佩的人),内容包括:① 简单说明他/她是谁;② 用具体事例说明你为什么觉得他/她美;③ 谈谈他/她让你学到了什么。要求:至少用三个主语从句(如 What impresses me most is… / It is true that… / Whoever …),句子地道、围绕中心。', 'The theme of this unit is true beauty. Write a short passage (about 80 words) introducing a person you think is truly beautiful (a family member, a friend or someone you admire). Include: 1) who the person is; 2) why you find them beautiful, with an example; 3) what they have taught you. Use at least three subject clauses (e.g. What impresses me most is…, It is true that…, Whoever…).', '["说明人物是谁(The person I admire most is …)","用主语从句讲为什么美(What impresses me most is …)","用形式主语 it 补充观点(It is clear that …)","谈收获、句句围绕''真正的美''这一中心"]'::jsonb, 70, 100, 'The most beautiful person I know is my grandmother. What impresses me most is not her face but her kindness. Whoever meets her feels welcome at once, because she listens with a warm and honest heart. It is true that her hair is grey and her hands are rough, yet everyone says she shines. What she taught me is simple: real beauty comes from how we treat others. Whether we are young or old, that gentle kind of beauty never fades away.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["What impresses me most is not her face but her kindness.","Whoever meets her feels welcome at once.","It is true that her hair is grey, yet everyone says she shines.","Whether we are young or old, that gentle beauty never fades away."]'::jsonb, '[{"wrong":"What impresses me most are her kindness.","correct":"What impresses me most is her kindness.","note":"what 引导的主语从句作主语时,谓语动词通常用单数 is。"},{"wrong":"Is important that we value inner beauty.","correct":"It is important that we value inner beauty.","note":"主语从句后置,句首必须用形式主语 it。"},{"wrong":"If we should care about looks is hard to say.","correct":"Whether we should care about looks is hard to say.","note":"句首主语从句表''是否''用 whether,不用 if。"}]'::jsonb, '【真正的美·人物介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (12, 'elective3', 'U1', '{"title":"主语从句(what / that / whether · 形式主语 it)速查","intro":"主语从句就是''一个句子充当主语''。判断口诀:从句缺主语/宾语→用 what;从句完整说事实→用 that;表''是否''→用 whether;为避免头重脚轻,常把从句后置、句首用形式主语 it。","table":{"headers":["连接词","用法 / 例句"],"rows":[["what","从句内缺成分(= the thing that):What I say is true.(say 缺宾语)"],["that","从句完整、陈述事实(只连接、不作成分):That she tried hard is clear."],["whether","表''是否''(开放/未定;句首不用 if):Whether it matters is debated."],["it(形式主语)","把从句后置:It is true that … / It takes courage to do …"],["whoever / whatever","指人/物作主语:Whoever tries will succeed. / Whatever you post stays."]]},"specialRules":[{"rule":"从句缺主语或宾语 → 用 what(不能用 that)","mark":"What matters is health.(matters 缺主语→what)"},{"rule":"从句结构完整、是事实 → 用 that;that 不充当成分但不能省","mark":"That he changed surprised us."},{"rule":"句首主语从句表''是否''只能用 whether,绝不用 if","mark":"Whether it works is unknown.(×If)"},{"rule":"to do / that / whether 作主语常后置,句首用形式主语 it","mark":"It is hard to say. / It is clear that …"}],"why":["what = the thing that,本身在从句里当主语或宾语,所以能补足缺成分;that 只起连接、不补成分,故从句必须完整;英语不喜欢主语太长,于是用 it 占位、把真正的主语从句挪到句尾。"],"gaokaoPoints":["what 与 that 的区分:看从句是否缺主语/宾语(缺→what,完整→that);语法填空高频。","句首''是否''用 whether 不用 if;whoever/whatever 引导主语从句作主语。","It is + adj./n. + that/to do 的形式主语结构,书面表达高分句型。"],"examVsReal":[{"exam":"What he said is true.(考试/书面)","real":"The thing he said is true.","note":"考试爱考 what 主语从句;口语里常换成 the thing (that)…"},{"exam":"It is important that we accept ourselves.(考试)","real":"Accepting ourselves is important.","note":"考试用形式主语 it;口语常直接用动名词作主语,更简洁"}]}'::jsonb, 'fltrp');
